INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(92982, 'ruRU', 'Что здесь делают аракоа? И кто это?', '', 24330),
(92983, 'ruRU', 'Эта Актар. Последователи Сете и Совета Теней собираются в руинах неподалёку, и он за ними приглядывает. Ещё тут летучие аракоа безобразничают. Тут помёта птичьего до фига надо убирать.$b$bЕщё если тебе на восток надо, тут большой туннель на юго-востоке, прямо к Айронхолдской гавани выведет. Только опасно может быть.', '', 24330),
(92984, 'ruRU', 'Тепереча время показать, чему мы научились!', '', 24330),
(92985, 'ruRU', 'Как ты смеешь прерывать моё наставление!', '', 24330),
(92986, 'ruRU', 'Аах... я могу использовать твою душу для следующего урока!', '', 24330),
(92987, 'ruRU', 'Командир! У меня новости! Я могу рассказать про Айронхолдскую гавань, Кузню Скверны и Трон Кил\'джедена.', '', 24330),
(92988, 'ruRU', 'Расскажи, что происходит в Айронхолдской гавани.', '', 24330),
(92989, 'ruRU', 'Похоже, Гулдан созывает всю Железную Орду со всего Дренора. Они прибывают в гавань на кораблях... а затем идут на восток... к ямам.$b$bТам их... превращают... в орков Скверны. Это ужасно. Мы должны уничтожить это место немедленно!', '', 24330),
(92990, 'ruRU', 'Это был твой друг? Он умер достойно... спас меня...', '', 24330),
(92991, 'ruRU', 'Что здесь произошло?', '', 24330),
(92992, 'ruRU', 'Твой воин пытался спасти меня, но мои похитители нас настигли. Мне жаль твоего друга.$b$bТам, на горе, Громмаш убил могущественного демона. Какое-то время это место пустовало, но теперь у Железной Орды новый хозяин... который снова заинтересовался им. Приспешники Гулдана призывают демонов и поддерживают течение осквернённых вод.$b$bТам, наверху, крайне опасно, тебе не стоит идти туда одному.', '', 24330),
(92993, 'ruRU', 'Приветствую, могу ли я чем-то помочь?', '', 24330),
(92994, 'ruRU', 'Ты Лагар? Я принёс весть от шамана твоего ордена. Он сказал... Гулдан знает. Могу я спросить, что это значит?', '', 24330),
(92995, 'ruRU', 'Спасибо, друг. Это значит, что древняя тайна открылась худшему из возможных людей.$b$bМне нужно будет призвать остальных членов моего ордена, чтобы защитить её.$b$bТы ведёшь армию, противостоящую Гулдану? Тебе здесь рады, и мы поможем, чем сможем. Нас немного, но стихийные силы Дренора нас уважают.$b$bОб этой тайне мы поговорим позже. Иди с миром.', '', 24330),
(92996, 'ruRU', 'Получить удар этим — очень больно.', '', 24330),
(92997, 'ruRU', 'Ты... ты начинаешь меня БЕСИТЬ!!', '', 24330),
(92998, 'ruRU', '<Великий дракон кивает вам с улыбкой.>', '', 24330),
(92999, 'ruRU', 'Срочное сообщение для Сенегоса!', '', 24330),
(93000, 'ruRU', 'Ночнорождённые напали на земли дракончиков.', '', 24330),
(93001, 'ruRU', 'Этих четырёх дракончиков нужно немедленно обработать лей-кристаллами.', '', 24330),
(93002, 'ruRU', 'Ты доброе маленькое создание, $n.', '', 24330),
(93004, 'ruRU', 'Погоди... что это у тебя в руках?', '', 24330),
(93005, 'ruRU', 'Я ТЕБЯ УБЬЮ! Я ВЫРВУ ТЕБЕ СЕРДЦЕ!', '', 24330),
(93006, 'ruRU', 'Пришёл освободить этого жалкого дракона, охотник на демонов?', '', 24330),
(93047, 'ruRU', 'Тебе здесь не место.', '', 24330),
(93048, 'ruRU', 'Это место не для тебя.', '', 24330),
(93049, 'ruRU', 'Мы помним королеву.', '', 24330),
(93050, 'ruRU', 'За Азшару!', '', 24330),
(93064, 'ruRU', 'Повторное зажжение', '', 24330),
(93073, 'ruRU', 'Отлично, у тебя получается всё лучше! Скоро ты будешь готов призвать своего первого бесёнка!', '', 24330),
(93074, 'ruRU', 'Сохраняй сосредоточенность и подчиняй хаос своей воле.', '', 24330),
(93075, 'ruRU', 'Разум твой должен быть крепок, как у огра! Если слаб — умрёшь. Наш путь прост, вот так.', '', 24330),
(93080, 'ruRU', 'Подожди всего секунду, пока я снимаю печать.', '', 24330);
